package in.ac.rtu.medicare.service;
import in.ac.rtu.medicare.dao.AppointmentDao; import in.ac.rtu.medicare.model.Appointment; import in.ac.rtu.medicare.util.Validation; import java.sql.SQLException; import java.time.*; import java.util.*;
public class AppointmentService { private final AppointmentDao dao=new AppointmentDao(); public long book(long patientUser,long doctorId,String dateTime,String reason)throws SQLException {LocalDateTime at=LocalDateTime.parse(dateTime);Validation.future(at);return dao.create(dao.patientIdForUser(patientUser),doctorId,at,Validation.required(reason,"Reason"));} public void cancel(long patientUser,long appointment)throws SQLException {dao.cancel(appointment,dao.patientIdForUser(patientUser));} public List<Appointment> history(long user)throws SQLException{return dao.forPatient(dao.patientIdForUser(user));} public List<Appointment> schedule(long user)throws SQLException{return dao.forDoctor(dao.doctorIdForUser(user));} }
